import { useState } from 'react'
import { describeError } from '../api/client'
import { useSession } from '../session/session-context'

// Downloads a PDF generated by the API (quote or sales order). The server
// applies the same access rules as viewing the document.
export function DownloadPdfButton({ path, fallbackName }: { path: string; fallbackName: string }) {
  const { download } = useSession()
  const [busy, setBusy] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const run = async () => {
    setBusy(true)
    setError(null)
    try {
      const { blob, filename } = await download(path)
      const url = URL.createObjectURL(blob)
      const link = document.createElement('a')
      link.href = url
      link.download = filename ?? `${fallbackName}.pdf`
      document.body.append(link)
      link.click()
      link.remove()
      setTimeout(() => URL.revokeObjectURL(url), 10_000)
    } catch (err) {
      setError(describeError(err))
    } finally {
      setBusy(false)
    }
  }

  return (
    <>
      <button type="button" className="button button-secondary" disabled={busy} onClick={() => void run()}>
        {busy ? 'Generando PDF…' : 'Descargar PDF'}
      </button>
      {error ? <span className="field-error" role="alert">{error}</span> : null}
    </>
  )
}
